#!/usr/bin/env python3
"""Vendor a C library into db/third_party, for the Go build to compile.

    update.py quickjs <checkout>                 a QuickJS git checkout at the commit to vendor
    update.py sqlite <dir> <url> <sha3-256>      an unzipped SQLite amalgamation, where it came
                                                 from, and the SHA3-256 sqlite.org publishes

Each vendored file gets a header naming its origin, version, and license, per the repo's
vendoring rules.  Each of the library's C files gets a wrapper, db/internal/<lib>/lib_<name>.c,
which sets the defines its own build would pass and includes it: cgo compiles only C files in the
package directory, and hashes only those into its build cache, so a wrapper that names the
vendored version makes an update rebuild.  The library's entry in the root NOTICE is rewritten
too.
"""

import os
import re
import subprocess
import sys

DB = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
NOTICE = os.path.join(os.path.dirname(DB), "NOTICE")

SQLITE_BLESSING = """The author disclaims copyright to this source code.  In place of
a legal notice, here is a blessing:

   May you do good and not evil.
   May you find forgiveness for yourself and forgive others.
   May you share freely, never taking more than you give."""


def comment(lines):
    """lines as the body of a C block comment"""
    return "\n".join((" * " + line).rstrip() for line in lines)


def header(origin, spdx, license_text):
    return "/*!\n" + comment(origin + ["Unmodified.", "", "SPDX-License-Identifier: " + spdx, ""]
                           + license_text.strip().splitlines()) + "\n */\n"


def vendor(lib, files, src, origin_of, spdx, license_text):
    """copy each file from src into third_party/<lib>, headed"""
    out = os.path.join(DB, "third_party", lib)
    os.makedirs(out, exist_ok=True)
    for name in os.listdir(out):
        os.remove(os.path.join(out, name))
    for name in files:
        with open(os.path.join(src, name), encoding="utf-8", errors="surrogateescape") as f:
            body = f.read()
        with open(os.path.join(out, name), "w", encoding="utf-8", errors="surrogateescape") as f:
            f.write(header(origin_of(name), spdx, license_text) + body)


def wrapper(name, lib, source, provenance, defines):
    """db/internal/<lib>/lib_<name>.c, which compiles third_party/<lib>/<source> under defines"""
    lines = [
        "// Generated by third_party/update.py from " + provenance + ":",
        "// compiles the vendored " + source + " with the defines its own build passes.",
    ]
    for d in defines:
        lines.append(d)
    lines.append('#include "../../third_party/%s/%s"' % (lib, source))
    with open(os.path.join(DB, "internal", lib, "lib_%s.c" % name), "w") as f:
        f.write("\n".join(lines) + "\n")


def notice(title, entry):
    """rewrite the NOTICE entry whose first line starts with title, or append one"""
    with open(NOTICE) as f:
        text = f.read().rstrip("\n")
    chunks = text.split("\n\n\n")
    for i, chunk in enumerate(chunks):
        if chunk.startswith(title + " "):
            chunks[i] = entry
            break
    else:
        chunks.append(entry)
    with open(NOTICE, "w") as f:
        f.write("\n\n\n".join(chunks) + "\n")


def quickjs(checkout):
    commit = subprocess.check_output(["git", "-C", checkout, "rev-parse", "HEAD"], text=True).strip()
    if subprocess.check_output(["git", "-C", checkout, "status", "--porcelain"], text=True).strip():
        sys.exit("the QuickJS checkout has local changes")
    with open(os.path.join(checkout, "VERSION")) as f:
        version = f.read().strip()
    with open(os.path.join(checkout, "LICENSE")) as f:
        license_text = f.read()

    # the library's sources, and every header they include
    sources = ["quickjs.c", "libregexp.c", "libunicode.c", "cutils.c", "dtoa.c"]
    headers = ["quickjs.h", "quickjs-atom.h", "quickjs-opcode.h", "libregexp.h",
               "libregexp-opcode.h", "libunicode.h", "libunicode-table.h", "cutils.h", "dtoa.h",
               "list.h"]
    origin = lambda name: [
        "Vendored from QuickJS by Fabrice Bellard and Charlie Gordon,",
        "https://github.com/bellard/quickjs, file %s," % name,
        "at commit %s (version %s)." % (commit, version),
    ]
    vendor("quickjs", sources + headers, checkout, origin, "MIT", license_text)

    # the defines QuickJS's makefile passes; -fwrapv is in quickjs.go's cgo flags, since a define
    # cannot carry it
    provenance = "QuickJS %s at commit %s" % (version, commit[:7])
    defines = [
        "#ifndef _GNU_SOURCE",
        "#define _GNU_SOURCE",
        "#endif",
        '#define CONFIG_VERSION "%s"' % version,
        "#ifdef _WIN32",
        "#define __USE_MINGW_ANSI_STDIO 1",
        "#endif",
        # QuickJS assigns strrchr's result on a const string to a plain pointer
        "#if defined(__clang__)",
        '#pragma clang diagnostic ignored "-Wincompatible-pointer-types-discards-qualifiers"',
        "#elif defined(__GNUC__)",
        '#pragma GCC diagnostic ignored "-Wdiscarded-qualifiers"',
        "#endif",
    ]
    for source in sources:
        wrapper(source[:-2].replace("-", "_"), "quickjs", source, provenance, defines)

    notice("QuickJS", "\n".join([
        "QuickJS %s, commit %s" % (version, commit[:7]),
        "https://github.com/bellard/quickjs",
        "",
        license_text.strip(),
        "",
        "Used for the JavaScript runtime in the database, in these files:",
        "",
        "    - db/third_party/quickjs/",
    ]))


def sqlite(src, url, sha3):
    with open(os.path.join(src, "sqlite3.h")) as f:
        version = re.search(r'#define SQLITE_VERSION\s+"([^"]+)"', f.read()).group(1)
    origin = lambda name: [
        "Vendored from the SQLite %s amalgamation, file %s," % (version, name),
        "%s (SHA3-256 %s)." % (url, sha3),
    ]
    vendor("sqlite", ["sqlite3.c", "sqlite3.h"], src, origin, "blessing", SQLITE_BLESSING)

    # extension loading would need -ldl and dlopen, which the database never uses
    wrapper("sqlite3", "sqlite", "sqlite3.c", "SQLite %s" % version, [
        "#define SQLITE_OMIT_LOAD_EXTENSION 1",
    ])

    notice("SQLite", "\n".join([
        "SQLite %s" % version,
        "https://www.sqlite.org/",
        "",
        SQLITE_BLESSING,
        "",
        "Used for the database's storage, in these files:",
        "",
        "    - db/third_party/sqlite/",
    ]))


if __name__ == "__main__":
    if len(sys.argv) == 3 and sys.argv[1] == "quickjs":
        quickjs(sys.argv[2])
    elif len(sys.argv) == 5 and sys.argv[1] == "sqlite":
        sqlite(sys.argv[2], sys.argv[3], sys.argv[4])
    else:
        sys.exit(__doc__)
